function mirror_pose_UI()
{
	var checkExist = ActiveSceneRoot.Properties("MirrorPose");
	if(checkExist)
	{
		DeleteObj(checkExist);
	} 
	
		//create ppg	
		var oPpg = ActiveSceneRoot.AddProperty("CustomProperty",false,"MirrorPose");
		var layout = oPpg.PPGLayout;
		
		layout.AddGroup("Global: Use ValveBiped as the Axis");
			layout.AddRow();
				layout.AddButton("mirror_pose" , "Mirror Selected");		
				layout.AddButton("flip_pose" , "Flip Pose");	
			layout.EndRow();
		layout.EndGroup();
		
		layout.AddGroup("Local: Use Local Center of Mass as the Axis");
			layout.AddRow();
				layout.AddButton("mirror_pose_loc" , "Mirror Selected");	
				layout.AddButton("flip_pose_loc" , "Flip Pose");	
			layout.EndRow();
		layout.EndGroup(); 

			
		layout.Logic =  mirror_pose_OnClicked.toString() +
										mirror_pose_loc_OnClicked.toString() +
										flip_pose_OnClicked.toString()+
										flip_pose_loc_OnClicked.toString();
						
		layout.Language = "JScript";
		InspectObj(oPpg, null, null, 3 );
} 	


function mirror_pose_OnClicked(local_global)
{
	if (!selection.count)
		{
			logmessage ("Select Something",siFatal);
		}
		
	num_sel = selection.count;
	//make a collecton of all the items
	selected_items = new ActiveXObject("XSI.Collection");
	for (x = 0; x < num_sel;x++)
		{
			selected_items.AddItems(selection(x));
		}
	for (i = 0; i < selected_items.count;i++)
	{
		obj = selected_items(i);
		//get the selected objects transforms
		px = (obj.posx.Value);
		py = (obj.posy.Value);
		pz = (obj.posz.Value);
		rx = (obj.rotx.Value);
		ry = (obj.roty.Value);
		rz = (obj.rotz.Value);
		
		//see if it is on the left or right side by checking the last letter
		lastletter = obj.name.slice(-1);
		firstletter = obj.name.slice(0,1);
		//sometimes the controls are duplicated so check for that too
		lasttwoletters = obj.name.slice(-2);
		//foot controls are named "Left" and "Right" so check for that too
		left = obj.name.match("Left");
		right = obj.name.match("Right");
		//and to round things out fingers have "_L_" or "_R_" stuck in the middle somewhere
		left_finger = obj.name.match("_L_");
		right_finger = obj.name.match("_R_");
		//not done yet, since there is no R upvecotr parent object things get messy with 
		//the upvectors
		armupvectors = obj.name.match("ArmUpV");
		legupvectors = obj.name.match("UpVParent");
		armcheck = obj.name.match("Arm");
		parentcheck = obj.name.match("Parent");
		parentcheck1 = obj.name.match("Parent1");
		legup = obj.name.match("Leg_Up");

		//all the left side objects
		if (lastletter == "L" || lasttwoletters == "L1" || left || left_finger || armupvectors || legupvectors )
			{
				var cut;
				if (left)
				{
					replace = obj.name.replace ("Left", "Right");
					newname = ("ValveBiped." + replace);
				}
				else
				{
					if (left_finger)
						{
							replace = obj.name.replace ("_L_", "_R_");
							newname = ("ValveBiped." + replace);
						}
						else
						{
							if (armupvectors)
							{
								if (parentcheck)
								{
										if (parentcheck1)
										{
										replace = ("lArmUpVParent");
										}
										else
										{
										replace = ("lArmUpVParent1");
										}
								}
								else
								{	
									if (firstletter == "l")
									{
									replace = obj.name.replace ("lArm", "rArm");
									}
									else
									{
										replace = obj.name.replace ("rArm", "lArm");
									}
									if (firstletter == "L")
									{
										replace = obj.name.replace ("LArm", "RArm");
									}
									else
									{
									replace = obj.name.replace ("RArm", "LArm");
									}

								}
							newname = ("ValveBiped." + replace);	
							}
							else
							{
								if (legupvectors && !armcheck)
								{
									if (firstletter == "L")
									{
									replace = obj.name.replace ("LUpV", "RUpV");
									}
									else
									{
									replace = obj.name.replace ("RUpV", "LUpV");
									}
									newname = ("ValveBiped." + replace);	
								}
								else
								{
								//change L to R by trimming the L and adding R
								strlength = obj.name.length;
								cut = (strlength - 1);
								slice = obj.name.slice(0,cut);
								newname = ("ValveBiped." + slice + "R");
								}
							}
						}	
					}
					SelectObj(newname);
					mirobj = Selection(0);
					if (legup)
					{
						mirobj.posx.Value = (px);
					}
					else
					{
						mirobj.posx.Value = (px * (-1));
					}
					mirobj.posy.Value = (py);
					mirobj.posz.Value = pz;
					
					if (left)
					{
					mirobj.rotx.Value = (rx);
					mirobj.roty.Value = (ry * (-1));
					mirobj.rotz.Value = (rz * (-1));		
					}
					else
					{
					mirobj.rotx.Value = (rx * (-1));
					mirobj.roty.Value = (ry * (-1));
					mirobj.rotz.Value = rz;		
					}
		}
		else
		{
			if (lastletter == "R" || lasttwoletters == "R1" || right || right_finger || armupvectors)
				{
					var cut;
//					logmessage (obj + " is on the right side");
					if (right)
					{
						replace = obj.name.replace ("Right", "Left");
						newname = ("ValveBiped." + replace);
					}
					else
					{
						if (right_finger)
							{
								replace = obj.name.replace ("_R_", "_L_");
								newname = ("ValveBiped." + replace);
							}
							else
							{
								if (armupvectors == "rArm")
								{
									replace = obj.name.replace ("rArm", "lArm");
									newname = ("ValveBiped." + replace);
								}
								else
								{
								//change R to L by trimming the R and adding L
								strlength = obj.name.length;
								cut = (strlength - 1);
								slice = obj.name.slice(0,cut);
								newname = ("ValveBiped." + slice + "L");
								}
							}
					}
					SelectObj(newname);
//					logmessage ("Mirroring " + newname); 
					mirobj = Selection(0);
					if (legup)
					{
					mirobj.posx.Value = (px);
					}
					else
					{
					mirobj.posx.Value = (px * (-1));
					}
					mirobj.posy.Value = py;
					mirobj.posz.Value = pz;
					if (right)
					{
						mirobj.rotx.Value = (rx);
					}
					else
					{
					mirobj.rotx.Value = (rx * (-1));
					}					
					mirobj.roty.Value = (ry * (-1));
					mirobj.rotz.Value = rz;					
				}
				else
				{
//					logmessage (obj + " is in the middle");
					//because every object has different rotation order
					//there are all these special cases..nice
					if (obj.name == "Bip01_Pelvis" || obj.name == "UpperBody")
					{
					obj.rotz.Value = (rz * (-1));
					obj.roty.Value = (ry * (-1));	
					obj.posx.Value = (px * (-1));
					}
					else
					{
					obj.roty.Value = (ry * (-1));
					obj.rotx.Value = (rx * (-1));
					}
				}
			}
		}
		DeselectAll();
}


