function flip_pose_OnClicked()
{
	SelectMembers("ValveBiped.Plotted", null, null);
	num_sel = selection.count;
	//make a collecton of all the items
	selected_items = new ActiveXObject("XSI.Collection");
	for (x = 0; x < num_sel;x++)
		{
			selected_items.AddItems(selection(x));
		}
	for (i = 0; i < selected_items.count;i++)
	{
		
		obj = selected_items(i);
		//get the position of the first item
		px = (obj.posx.Value);
		py = (obj.posy.Value);
		pz = (obj.posz.Value);
		
		rx = (obj.rotx.Value);
		ry = (obj.roty.Value);
		rz = (obj.rotz.Value);

		
		//find out the mirror item and get it's position
		//we are only doing this for left side and middle items
		//since left side will flip with the right 
		//see if it is on the left or right side by checking the last letter
		lastletter = obj.name.slice(-1);
		firstletter = obj.name.slice(0,1);
		//sometimes the controls are duplicated so check for that too
		lasttwoletters = obj.name.slice(-2);
		//foot controls are named "Left" and "Right" so check for that too
		left = obj.name.match("Left");
		right = obj.name.match("Right");
		//and to round things out fingers have "_L_" or "_R_" stuck in the middle somewhere
		left_finger = obj.name.match("_L_");
		right_finger = obj.name.match("_R_");
		//not done yet, since there is no R upvector parent object things get messy with 
		//the upvectors
		armupvectors = obj.name.match("ArmUpV");
		legupvectors = obj.name.match("UpVParent");
		legup = obj.name.match("Leg_Up");
		armcheck = obj.name.match("Arm");
		parentcheck = obj.name.match("Parent");
		parentcheck1 = obj.name.match("Parent1");
		
		if (lastletter == "L" || lasttwoletters == "L1" || left || left_finger|| legupvectors || legupvectors || firstletter == "L" || firstletter == "l")
		{
//			logmessage (obj);
			var cut;
			if (left)
			{
				replace = obj.name.replace ("Left", "Right");
				mirror= ("ValveBiped." + replace);
			}
			else
			{
				if (left_finger)
				{
						replace = obj.name.replace ("_L_", "_R_");
						mirror = ("ValveBiped." + replace);
				}
				else
				{
					if (lastletter == "L")
					{
					//change L to R by trimming the L and adding R
					strlength = obj.name.length;
					cut = (strlength - 1);
//					logmessage (cut);
					slice = obj.name.slice(0,cut);
					mirror = ("ValveBiped." + slice + "R");
					}
					else
					{
						if (armupvectors && firstletter == "l")
						{
							replace = obj.name.replace ("lArm", "rArm");
							mirror = ("ValveBiped." + replace);
						}
						else
						{
							if (armupvectors && firstletter == "L")
							{
								replace = obj.name.replace ("LArm", "RArm");
								mirror = ("ValveBiped." + replace);
								}
							else
							{
							if (legupvectors && !armcheck)
								{
								if (firstletter == "l")
								{
								//change L to R by trimming the L and a
								strlength = obj.name.length;           
								cut = (strlength);                 
								slice = obj.name.slice(1,cut);         
								mirror = ("ValveBiped.r" + slice);
								}
							}
							else
							{						
						//change L to R by trimming the L and a
						strlength = obj.name.length;           
						cut = (strlength - 1);                 
						slice = obj.name.slice(0,cut);         
						mirror = ("ValveBiped." + slice + "R");
					}
					}   
				}   
			}
			}
		}
//			logmessage (obj + "'s mirror = " + mirror);		


					//mirror is the mirrored object
					SelectObj(mirror);
					mir_obj = Selection(0);
					
					//get the mirror objects transform values
					mir_px = (mir_obj.posx.Value);
					mir_py = (mir_obj.posy.Value);
					mir_pz = (mir_obj.posz.Value);          
					mir_rx = (mir_obj.rotx.Value);
					mir_ry = (mir_obj.roty.Value);
					mir_rz = (mir_obj.rotz.Value);
				
					
//					//apply transforms to mirrored object
//					if (obj.name == "lArmUpV" || obj.name == "LArmUpV")
//					{
//						obj.posx.Value = mir_px * (-1);qq
//						obj.posy.Value = mir_py;
//						obj.posz.Value = mir_pz;
//						obj.rotx.Value = (mir_rx);
//						obj.roty.Value = (mir_ry * (-1));
//						obj.rotz.Value = (mir_rz * (-1));	
//					}
//						if (mir_obj.name == "rArmUpV" || mir_obj.name == "RArmUpV")
//						{
//							mir_obj.posx.Value = (px * (-1));
//							mir_obj.posy.Value =  py;
//							mir_obj.posz.Value =  pz
//							mir_obj.rotx.Value = (rx * (-1));
//							mir_obj.roty.Value = (ry * (-1));
//							mir_obj.rotz.Value =  rz;	
//					}

         
					if (left || firstletter == "l" || firstletter == "L")
					{
						if (legup)
						{
							mir_obj.posx.Value = px;
						}
						else
						{
 							mir_obj.posx.Value = px * (-1); 
 						}
							mir_obj.posy.Value = py;
							mir_obj.posz.Value = pz;
							mir_obj.rotx.Value = (rx);
							mir_obj.roty.Value = (ry * (-1));
							mir_obj.rotz.Value = (rz * (-1));
						
     				if (legup)
     				{
							obj.posx.Value = (mir_px); 
						}
						else
						{
							obj.posx.Value = (mir_px * (-1)); 
						}
						obj.posy.Value = mir_py;
						obj.posz.Value = mir_pz;
						obj.rotx.Value = (mir_rx);
						obj.roty.Value = (mir_ry * (-1));
						obj.rotz.Value = (mir_rz * (-1));	
					}
					else
					{

					//apply the mirrored objects transforms to the original object
					SelectObj(obj);
					obj.posx.Value = (mir_px * (-1));
					obj.posy.Value =  mir_py;
					obj.posz.Value =  mir_pz;
					//apply original objects transforms to the mirror object
					SelectObj(mirror);
					mir_obj.posx.Value = (px * (-1));
					mir_obj.posy.Value =  py;
					mir_obj.posz.Value =  pz;
					
					obj.rotx.Value = (mir_rx * (-1));
					obj.roty.Value = (mir_ry * (-1));
					obj.rotz.Value =  mir_rz;		
					
					mir_obj.rotx.Value = (rx * (-1));
					mir_obj.roty.Value = (ry * (-1));
					mir_obj.rotz.Value =  rz;	
					}
		}
		else
		{
				if (lastletter != "R" || lasttwoletters != "R1" || !right|| !right_finger)
				{       
		
					//because every object has different rotation order
					//there are all these special cases..nice
				

					if (obj.name == "Bip01_Pelvis" || obj.name == "UpperBody")
					{
						obj.rotz.Value = (rz * (-1));
						obj.roty.Value = (ry * (-1));	
					}
					else
					{ 
						obj.roty.Value = (ry * (-1));
						obj.rotx.Value = (rx * (-1));
					} 
					if (obj.name == "UpperBody")
					{	
     
						obj.posx.Value = (px * (-1));            
					}

			}     
		}
		}         
	DeselectAll();
}

function flip_pose_loc_OnClicked()
{
	SelectMembers("ValveBiped.Plotted", null, null);
	num_sel = selection.count;
	//make a collecton of all the items
	selected_items = new ActiveXObject("XSI.Collection");
	for (x = 0; x < num_sel;x++)
		{
			selected_items.AddItems(selection(x));
		}
	for (i = 0; i < selected_items.count;i++)
	{
		
		obj = selected_items(i);
		//get the position of the first item
		px = (obj.posx.Value);
		py = (obj.posy.Value);
		pz = (obj.posz.Value);
		
		rx = (obj.rotx.Value);
		ry = (obj.roty.Value);
		rz = (obj.rotz.Value);

		
		//find out the mirror item and get it's position
		//we are only doing this for left side and middle items
		//since left side will flip with the right 
		//see if it is on the left or right side by checking the last letter
		lastletter = obj.name.slice(-1);
		firstletter = obj.name.slice(0,1);
		//sometimes the controls are duplicated so check for that too
		lasttwoletters = obj.name.slice(-2);
		//foot controls are named "Left" and "Right" so check for that too
		left = obj.name.match("Left");
		right = obj.name.match("Right");
		//and to round things out fingers have "_L_" or "_R_" stuck in the middle somewhere
		left_finger = obj.name.match("_L_");
		right_finger = obj.name.match("_R_");
		//not done yet, since there is no R upvector parent object things get messy with 
		//the upvectors
		armupvectors = obj.name.match("ArmUpV");
		legupvectors = obj.name.match("UpVParent");
		legup = obj.name.match("Leg_Up");
		armcheck = obj.name.match("Arm");
		parentcheck = obj.name.match("Parent");
		parentcheck1 = obj.name.match("Parent1");
		//ok time to do some center of mass stuff
		//assuming 1/2 the distance between the feet is a good place to start
		//get those numbers
		var lfootx;
		var rfootx;
		var centerx;
		var dist;
		var obj_px;
		var mirror;
		var mirror_pos;
		rfoot = "ValveBiped.RightFoot";
		lfoot = "ValveBiped.LeftFoot";
		SelectObj(rfoot);
		robj = Selection(0);
		rfootx = robj.posx.Value;
		SelectObj(lfoot);
		lobj = Selection(0);
		lfootx = lobj.posx.Value;     
		//centerx is local YZ plane we will mirror across
		centerx = ((((lfootx - rfootx)/2) + rfootx));
		//now find it for the feet, which is the x pos of the upper body control
		upperbody = ("ValveBiped.UpperBody");
		SelectObj(upperbody);
		center = Selection(0);
		center_of_mass = center.posx.Value; 
					
		if (lastletter == "L" || lasttwoletters == "L1" || left || left_finger|| legupvectors || legupvectors || firstletter == "L" || firstletter == "l")
		{
//			logmessage (obj);
			var cut;
			if (left)
			{
				replace = obj.name.replace ("Left", "Right");
				mirror= ("ValveBiped." + replace);
			}
			else
			{
				if (left_finger)
				{
						replace = obj.name.replace ("_L_", "_R_");
						mirror = ("ValveBiped." + replace);
				}
				else
				{
					if (lastletter == "L")
					{
					//change L to R by trimming the L and adding R
					strlength = obj.name.length;
					cut = (strlength - 1);
//					logmessage (cut);
					slice = obj.name.slice(0,cut);
					mirror = ("ValveBiped." + slice + "R");
					}
					else
					{
						if (armupvectors && firstletter == "l")
						{
							replace = obj.name.replace ("lArm", "rArm");
							mirror = ("ValveBiped." + replace);
						}
						else
						{
							if (armupvectors && firstletter == "L")
							{
								replace = obj.name.replace ("LArm", "RArm");
								mirror = ("ValveBiped." + replace);
								}
							else
							{
							if (legupvectors && !armcheck)
								{
								if (firstletter == "l")
								{
								//change L to R by trimming the L and a
								strlength = obj.name.length;           
								cut = (strlength);                 
								slice = obj.name.slice(1,cut);         
								mirror = ("ValveBiped.r" + slice);
								}
							}
							else
							{						
						//change L to R by trimming the L and a
						strlength = obj.name.length;           
						cut = (strlength - 1);                 
						slice = obj.name.slice(0,cut);         
						mirror = ("ValveBiped." + slice + "R");
							}
						}   
					}   
				}
			}
		}
//			logmessage (obj + "'s mirror = " + mirror);		
				SelectObj(mirror);

//				logmessage ("Mirroring " + newname); 
				mir_obj = Selection(0);
					//get the mirror objects transform values
				mir_px = (mir_obj.posx.Value);
				mir_py = (mir_obj.posy.Value);
				mir_pz = (mir_obj.posz.Value);          
				mir_rx = (mir_obj.rotx.Value);
				mir_ry = (mir_obj.roty.Value);
				mir_rz = (mir_obj.rotz.Value);
	
			       
					dist = px - center_of_mass ; 
					if (dist < 0)
						{
							dist = (dist *(-1));
						} 
			
					if (px < centerx)
						{          
						mirror_pos = center_of_mass  + dist;  
						}
					else
						{
						mirror_pos = center_of_mass  - dist;
						}
						
					//apply transforms to mirrored object
//					if (obj.name == "lArmUpV" || obj.name == "LArmUpV")
//					{
//						obj.posx.Value = mirror_pos * (-1);
//						obj.posy.Value = mir_py;
//						obj.posz.Value = mir_pz;
//						obj.rotx.Value = (mir_rx);
//						obj.roty.Value = (mir_ry * (-1));
//						obj.rotz.Value = (mir_rz * (-1));	
//					}
//						if (mir_obj.name == "rArmUpV")
//						{
//							mir_obj.posx.Value = (px * (-1));
//							mir_obj.posy.Value =  py;
//							mir_obj.posz.Value =  pz
//							mir_obj.rotx.Value = (rx * (-1));
//							mir_obj.roty.Value = (ry * (-1));
//							mir_obj.rotz.Value =  rz;	
//						}	  
					
						if (left || firstletter == "l" || firstletter == "L")
					{
						if (legup)
						{
						mir_obj.posx.Value = px;
						mir_obj.posy.Value = py;         
						mir_obj.posz.Value = pz;         
						mir_obj.rotx.Value = (rx);       
						mir_obj.roty.Value = (ry * (-1));
						mir_obj.rotz.Value = (rz * (-1));
						} 
						else
						{ 
 						mir_obj.posx.Value = mirror_pos; 
 						mir_obj.posy.Value = py;         
						mir_obj.posz.Value = pz;         
						mir_obj.rotx.Value = (rx);       
						mir_obj.roty.Value = (ry * (-1));
						mir_obj.rotz.Value = (rz * (-1));
 						}
     				if (legup)
     				{
						obj.posx.Value = (mir_px); 
						obj.posy.Value = mir_py;
						obj.posz.Value = mir_pz;
						obj.rotx.Value = (mir_rx);
						obj.roty.Value = (mir_ry * (-1));
						obj.rotz.Value = (mir_rz * (-1));	
						}
						else
						{
						if (left)
							{
								logmessage (obj);
							mir_dist = (-1 *(mir_px - center_of_mass)) ;
							obj.posx.Value = (center_of_mass + mir_dist); 
							}
						else
							{
							obj.posx.Value = (mir_px * (-1)); 
							}	
						obj.posy.Value = mir_py;
						obj.posz.Value = mir_pz;
						obj.rotx.Value = (mir_rx);
						obj.roty.Value = (mir_ry * (-1));
						obj.rotz.Value = (mir_rz * (-1));	
						}
					}
					else
					{
					//apply the mirrored objects transforms to the original object
					SelectObj(obj);
					obj.posx.Value = (mir_px * (-1));
					obj.posy.Value =  mir_py;
					obj.posz.Value =  mir_pz;
					//apply original objects transforms to the mirror object
					SelectObj(mirror);
					mir_obj.posx.Value = (px * (-1));
					mir_obj.posy.Value =  py;
					mir_obj.posz.Value =  pz;
					
					obj.rotx.Value = (mir_rx * (-1));
					obj.roty.Value = (mir_ry * (-1));
					obj.rotz.Value =  mir_rz;		
					
					mir_obj.rotx.Value = (rx * (-1));
					mir_obj.roty.Value = (ry * (-1));
					mir_obj.rotz.Value =  rz;	
					}
		}
		else
		{
				if (lastletter != "R" || lasttwoletters != "R1" || !right|| !right_finger)
				{       
		
					//because every object has different rotation order
					//there are all these special cases..nice
				

					if (obj.name == "Bip01_Pelvis" || obj.name == "UpperBody")
					{
						obj.rotz.Value = (rz * (-1));
						obj.roty.Value = (ry * (-1));	
					}
					else
					{ 
						obj.roty.Value = (ry * (-1));
						obj.rotx.Value = (rx * (-1));
					} 
				if (obj.name == "UpperBody")
					{
//						logmessage ("Mirroring Upper Body Locally");
						//now get how far pelvis is from the center
						obj_px = obj.posx.Value;                
//						logmessage ("UpBody's Position:" + obj_px);           
						dist = obj_px - centerx; 
						if (dist < 0)
							dist = (dist *(-1)); 
//						logmessage ("Center: " + centerx);                 
//						logmessage ("Distance From center:" + dist); 
						if (obj_px < centerx)
						{          
							mirror_pos = obj_px +(dist * 2);  
						}
						else
						{
							mirror_pos = obj_px - (dist * 2);
						}        
//						logmessage ("MirrorPos:" + mirror_pos);    
						obj.posx.Value = mirror_pos;            
					}

			}     
		}
		}         
	DeselectAll();
}